import{_ as n,o as t,c as a,a3 as e}from"./chunks/framework.CUr5VIp8.js";const b=JSON.parse('{"title":"第 1.1 章 物联网核心架构","description":"","frontmatter":{},"headers":[],"relativePath":"part1-fundamentals/1.1-iot-architecture.md","filePath":"part1-fundamentals/1.1-iot-architecture.md","lastUpdated":1792382370000}'),p={name:"part1-fundamentals/1.1-iot-architecture.md"};function o(r,s,d,l,i,c){return t(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="第-1-1-章-物联网核心架构" tabindex="-1">第 1.1 章 物联网核心架构 <a class="header-anchor" href="#第-1-1-章-物联网核心架构" aria-label="Permalink to &quot;第 1.1 章 物联网核心架构&quot;">​</a></h1><blockquote><ul><li><strong>前置知识</strong>：HTTP 请求-响应模型、浏览器开发者工具的基本使用；不需要任何物联网背景</li><li><strong>预计学习时长</strong>：约 40 分钟</li><li><strong>配套代码</strong>：<a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/server/index.mjs" target="_blank" rel="noreferrer">server/index.mjs</a>、<a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/server/broker.mjs" target="_blank" rel="noreferrer">server/broker.mjs</a>、<a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/server/simulator.mjs" target="_blank" rel="noreferrer">server/simulator.mjs</a>、<a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/src/services/mqtt/index.ts" target="_blank" rel="noreferrer">src/services/mqtt/index.ts</a></li><li><strong>本章实操任务</strong>：2 项</li></ul></blockquote><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><ul><li>说出物联网四层架构中每一层的职责，并各举出一个代表技术；</li><li>用 ASCII 图画出一条遥测数据从设备到 ECharts 曲线的完整上行链路，以及一条控制指令的完整下行链路；</li><li>解释 Broker、Topic、QoS、保留消息、遗嘱（LWT）等核心术语，并在配套 demo 源码中定位它们的实现；</li><li>区分端、边、云三级形态，判断自己的业务何时需要引入边缘计算；</li><li>对比公有云 IoT 平台与自建 Broker 的取舍，按规模分级估算前端将要面对的消息量。</li></ul><h2 id="_1-1-1-四层架构与关键角色-数据从哪里来-到哪里去" tabindex="-1">1.1.1 四层架构与关键角色：数据从哪里来，到哪里去 <a class="header-anchor" href="#_1-1-1-四层架构与关键角色-数据从哪里来-到哪里去" aria-label="Permalink to &quot;1.1.1 四层架构与关键角色：数据从哪里来，到哪里去&quot;">​</a></h2><p>物联网系统无论多复杂，都可以拆成四层。先看总览（右侧标注了每一层在配套 demo 中的对应物）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 图示：物联网四层架构与 demo 的对应关系</span></span>
<span class="line"><span>┌──────────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 应用层   Web 监控台 / 移动 App / 大屏 / 业务系统                    │</span></span>
<span class="line"><span>│          demo：Vue3 + Pinia + ECharts 设备监控台（demo/src）       │</span></span>
<span class="line"><span>├─────────────────────────────↑↓───────────────────────────────────┤</span></span>
<span class="line"><span>│ 平台层   Broker / 设备管理 / 规则引擎 / 时序数据库 / 设备影子        │</span></span>
<span class="line"><span>│          demo：aedes 内存 Broker（demo/server/broker.mjs）         │</span></span>
<span class="line"><span>├─────────────────────────────↑↓───────────────────────────────────┤</span></span>
<span class="line"><span>│ 网络层   TCP/TLS、WebSocket、Wi-Fi、蓝牙、LoRa、NB-IoT、4G/5G，    │</span></span>
<span class="line"><span>│          以及其上的 MQTT / CoAP / HTTP 等应用协议                   │</span></span>
<span class="line"><span>│          demo：TCP 1883（设备侧）+ WebSocket 8083（前端侧）         │</span></span>
<span class="line"><span>├─────────────────────────────↑↓───────────────────────────────────┤</span></span>
<span class="line"><span>│ 感知层   传感器 / MCU / 摄像头 / 执行器——真实世界里的&quot;物&quot;           │</span></span>
<span class="line"><span>│          demo：8 台模拟设备（demo/server/simulator.mjs）           │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────────────────────┘</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><p>注意图中的箭头是双向的：遥测数据上行，控制指令下行。分层不是要你在每一层都写代码，而是给你一张&quot;问题定位地图&quot;——曲线不动了，是感知层没采到、网络层丢了、平台层没转，还是应用层没画？每一层的职责与代表技术：</p><table tabindex="0"><thead><tr><th>层</th><th>核心职责</th><th>代表技术</th><th>demo 对应物</th></tr></thead><tbody><tr><td>感知层</td><td>采集物理量（温度、电量、功率），执行动作（开关、阀门）</td><td>温湿度传感器、MCU（ESP32 等）、RFID、摄像头、继电器</td><td><code>simulator.mjs</code> 模拟的 8 台设备</td></tr><tr><td>网络层</td><td>把数据从受限设备搬进 IP 世界，并选择传输与应用协议</td><td>Wi-Fi、蓝牙 Mesh、LoRa、NB-IoT、以太网；MQTT、CoAP、HTTP</td><td>本机回环：TCP 1883 / WS 8083</td></tr><tr><td>平台层</td><td>设备接入、消息路由、存储、规则联动、安全管理</td><td>aedes / EMQX / Mosquitto，规则引擎，时序数据库（TDengine 等）</td><td><code>broker.mjs</code>（aedes 内存实现）</td></tr><tr><td>应用层</td><td>把数据变成人可用的界面，把人的操作变成指令</td><td>Vue / React + ECharts / Three.js，移动端</td><td><code>demo/src</code> 下的设备监控台</td></tr></tbody></table><p>接下来是前端读 IoT 文档时的&quot;术语关&quot;。下表左边是概念，右边是它在 demo 里的落点，全部可以在源码中找到：</p><table tabindex="0"><thead><tr><th>术语</th><th>一句话定义</th><th>在 demo 中的落点</th></tr></thead><tbody><tr><td>设备（Device）</td><td>一台可寻址、有唯一 ID 的物理或虚拟终端</td><td><code>simulator.mjs</code> 中的 8 台设备，id 形如 <code>gh01-001</code></td></tr><tr><td>网关（Gateway）</td><td>帮受限网络设备接入 IP 世界的中间节点</td><td>demo 中被简化掉（模拟器自身就是&quot;设备&quot;）</td></tr><tr><td>Broker（消息枢纽）</td><td>MQTT 服务端，按 Topic 转发消息，不存储业务数据</td><td><code>broker.mjs</code>（aedes 内存实现）</td></tr><tr><td>规则引擎</td><td>平台上按条件（Topic/载荷/阈值）触发的服务端逻辑</td><td>demo 未启用；<code>alerts.ts</code> 注释保留了平台推送入口</td></tr><tr><td>时序数据库</td><td>按&quot;时间 + 指标&quot;优化的存储，支持降采样与聚合查询</td><td>demo 无持久化；前端用 120 点滑动窗口替代</td></tr><tr><td>设备影子</td><td>云端保存的设备最新状态快照，设备与界面各自异步读写</td><td>保留消息版 status 充当轻量影子</td></tr><tr><td>遥测（Telemetry）</td><td>周期上报的连续量：温度、湿度、功率</td><td><code>up/telemetry</code>，QoS 0</td></tr><tr><td>遥信（Status/离散量）</td><td>离散状态：在线/离线、开关开合</td><td><code>up/status</code> + telemetry 中的 <code>on</code> 字段</td></tr><tr><td>遥控（Command）</td><td>下行控制指令：开关、重启、设阈值</td><td><code>down/command</code>（QoS 1）</td></tr><tr><td>Topic</td><td>消息的&quot;地址&quot;，发布/订阅的路由依据</td><td><code>iot/{productId}/{deviceId}/{dir}/{kind}</code></td></tr><tr><td>QoS</td><td>服务质量等级 0/1/2（语义见第 1.3 章）</td><td>遥测用 0，状态/事件/指令用 1</td></tr><tr><td>保留消息（Retain）</td><td>Broker 为每个 Topic 保存最后一条 retain 报文，订阅瞬间送达</td><td>设备档案 status（<code>retain: true</code>）</td></tr><tr><td>遗嘱（LWT）</td><td>客户端异常掉线时，由 Broker 代发布的预设消息</td><td><code>simulator.mjs</code> 的 <code>will</code> 选项，掉线发布 offline</td></tr><tr><td>clientId</td><td>客户端身份；同 id 的两个连接会互踢</td><td>设备 <code>dev-{id}</code>，前端 <code>web-console_随机串</code></td></tr></tbody></table><p>其中&quot;保留消息 + 遗嘱&quot;这对组合，是前端<strong>打开页面瞬间就能看到完整设备清单</strong>的原因：订阅 <code>iot/+/+/up/status</code> 后，Broker 立刻回放每台设备 retain 的档案；设备拔电时遗嘱又会替它广播 offline。这两个语义会在第 1.3 章展开。</p><h2 id="_1-1-2-端-边-云-什么时候需要边缘计算" tabindex="-1">1.1.2 端-边-云：什么时候需要边缘计算 <a class="header-anchor" href="#_1-1-2-端-边-云-什么时候需要边缘计算" aria-label="Permalink to &quot;1.1.2 端-边-云：什么时候需要边缘计算&quot;">​</a></h2><p>把四层架构按&quot;算力放在哪&quot;重新折叠，就得到端-边-云三级形态：</p><ul><li><strong>端（设备侧）</strong>：传感器与 MCU，只做采集和最基础的执行；</li><li><strong>边（边缘网关/边缘服务器）</strong>：部署在设备附近（同一厂区、同一楼宇）的计算节点，就近处理数据、就近下发控制；</li><li><strong>云（平台侧）</strong>：集中接入、长期存储、跨地域分析与全局管理。</li></ul><p>demo 里没有独立的&quot;边&quot;——模拟设备直连云端 Broker。你可以想象把 <code>server/</code> 整个目录搬到一台树莓派上放进大棚，它就是一个最小边缘网关。什么时候值得引入这一层？出现以下任一信号时：</p><table tabindex="0"><thead><tr><th>信号</th><th>典型例子</th><th>边缘节点做什么</th></tr></thead><tbody><tr><td>时延敏感</td><td>工业产线急停要求毫秒级响应</td><td>就近判定，不等云端往返</td></tr><tr><td>断网自治</td><td>矿井、车载、仓库断外网仍要运转</td><td>本地缓存遥测 + 本地规则，恢复后再补传</td></tr><tr><td>带宽成本</td><td>200 路摄像头原始视频回传云端</td><td>边缘做识别，只回传结构化结果</td></tr><tr><td>数据合规</td><td>工厂数据不允许出园区</td><td>原始数据留在本地，云端只收汇总</td></tr></tbody></table><p>反过来，如果只是几百个温湿度传感器、秒级上报、没有实时控制诉求，&quot;端→云&quot;直连就是最简架构，别为不存在的问题买设备。前端同学尤其要意识到：<strong>边缘计算的引入会改变前端对接的对象</strong>——监控界面可能从&quot;连云平台&quot;变成&quot;连厂区边缘网关的本地 Web 服务&quot;，部署形态、鉴权方式、离线行为都会随之改变。</p><h2 id="_1-1-3-topic-契约与两条链路" tabindex="-1">1.1.3 Topic 契约与两条链路 <a class="header-anchor" href="#_1-1-3-topic-契约与两条链路" aria-label="Permalink to &quot;1.1.3 Topic 契约与两条链路&quot;">​</a></h2><p>demo 的所有消息都走一套 Topic 契约（定义在 <a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/src/services/mqtt/topics.ts" target="_blank" rel="noreferrer">topics.ts</a>）：</p><table tabindex="0"><thead><tr><th>Topic</th><th>方向</th><th>内容</th><th>QoS</th><th>保留消息</th></tr></thead><tbody><tr><td><code>iot/{productId}/{deviceId}/up/telemetry</code></td><td>设备→云</td><td>温湿度/电量/功率 JSON</td><td>0</td><td>否</td></tr><tr><td><code>iot/{productId}/{deviceId}/up/status</code></td><td>设备→云</td><td>在线状态与设备档案</td><td>1</td><td>是</td></tr><tr><td><code>iot/{productId}/{deviceId}/up/event</code></td><td>设备→云</td><td>告警事件（超温、低电）</td><td>1</td><td>否</td></tr><tr><td><code>iot/{productId}/{deviceId}/down/command</code></td><td>云→设备</td><td>控制指令</td><td>1</td><td>否</td></tr><tr><td><code>iot/{productId}/{deviceId}/down/command_reply</code></td><td>设备→云</td><td>指令回执</td><td>1</td><td>否</td></tr></tbody></table><p>配合报文样例，把契约落到字节级（载荷均为 JSON 字符串）：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 文件: demo/server/simulator.mjs —— 各 Topic 的报文样式</span></span>
<span class="line"><span>up/status            在线档案（QoS1 + retain）</span></span>
<span class="line"><span>  {&quot;online&quot;:true,&quot;name&quot;:&quot;育苗棚 A1 · 温湿度&quot;,&quot;product&quot;:{&quot;id&quot;:&quot;gh01&quot;,&quot;name&quot;:&quot;温湿度传感器&quot;},&quot;fw&quot;:&quot;v1.4.2&quot;,&quot;ip&quot;:&quot;192.168.1.20&quot;}</span></span>
<span class="line"><span>up/telemetry         普通遥测（QoS0）</span></span>
<span class="line"><span>  {&quot;mid&quot;:&quot;9f2c…&quot;,&quot;ts&quot;:1760700000000,&quot;temp&quot;:26.4,&quot;humi&quot;:57.2,&quot;battery&quot;:86,&quot;rssi&quot;:-58}</span></span>
<span class="line"><span>up/telemetry         低功耗批量（QoS0；samples 含 4 个缓存样本，设备时钟偏移约 +90s）</span></span>
<span class="line"><span>  {&quot;mid&quot;:&quot;31ab…&quot;,&quot;ts&quot;:1760700015000,&quot;samples&quot;:[{&quot;t&quot;:1760700006000,&quot;temp&quot;:26.8,&quot;humi&quot;:56.1,&quot;battery&quot;:85}, …]}</span></span>
<span class="line"><span>up/event             告警事件（QoS1）</span></span>
<span class="line"><span>  {&quot;mid&quot;:&quot;77de…&quot;,&quot;ts&quot;:1760700030000,&quot;code&quot;:&quot;TEMP_HIGH&quot;,&quot;level&quot;:&quot;error&quot;,&quot;message&quot;:&quot;温度 37.2℃ 超过阈值 35℃&quot;,&quot;value&quot;:37.2}</span></span>
<span class="line"><span>down/command         前端 → 设备（QoS1；id 用于关联回执）</span></span>
<span class="line"><span>  {&quot;id&quot;:&quot;c0ffee…&quot;,&quot;action&quot;:&quot;switch&quot;,&quot;params&quot;:{&quot;on&quot;:false},&quot;issuedAt&quot;:1760700060000}</span></span>
<span class="line"><span>down/command_reply   设备 → 前端（QoS1；按 id 找回发起方）</span></span>
<span class="line"><span>  {&quot;id&quot;:&quot;c0ffee…&quot;,&quot;ok&quot;:true,&quot;message&quot;:&quot;开关已关闭&quot;}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br></div></div><p><strong>上行链路：一条温度遥测的旅程。</strong> 对照下图逐条读源码，你会第一次&quot;看见&quot;数据流：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 图示：遥测上行链路（括号内为源码位置）</span></span>
<span class="line"><span>[simulator.mjs]            [broker.mjs]              [浏览器 Vue 监控台]</span></span>
<span class="line"><span> ① 每 4~8s 随机游走生成</span></span>
<span class="line"><span>   一条 JSON 遥测</span></span>
<span class="line"><span>  （reportSensor 函数）</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ ② QoS 0 发布到</span></span>
<span class="line"><span>      │    iot/gh01/gh01-001/up/telemetry</span></span>
<span class="line"><span>      ▼  ────── TCP 1883 ─────▶</span></span>
<span class="line"><span>                             aedes 按 Topic 匹配订阅者</span></span>
<span class="line"><span>                                 │</span></span>
<span class="line"><span>                                 │ ③ 同一个 broker 还挂着</span></span>
<span class="line"><span>                                 │    WebSocket 入口（8083 /mqtt）</span></span>
<span class="line"><span>                                 ▼  ───── WebSocket ─────▶</span></span>
<span class="line"><span>                                                      ④ mqtt.js 触发 message 事件</span></span>
<span class="line"><span>                                                        （connection.ts）</span></span>
<span class="line"><span>                                                            │</span></span>
<span class="line"><span>                                                      ⑤ IotGateway.route：</span></span>
<span class="line"><span>                                                        parseTopic 解析 + decodeTelemetry</span></span>
<span class="line"><span>                                                        校验/去重/纠时（codec.ts）</span></span>
<span class="line"><span>                                                            │</span></span>
<span class="line"><span>                                                      ⑥ devices store.ingestTelemetry：</span></span>
<span class="line"><span>                                                        追加进滑动窗口（上限 120 点，</span></span>
<span class="line"><span>                                                        stores/devices.ts）</span></span>
<span class="line"><span>                                                            │</span></span>
<span class="line"><span>                                                      ⑦ ECharts 追加一个点</span></span>
<span class="line"><span>                                                        （TelemetryChart.vue）</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br></div></div><p><strong>下行链路：一次&quot;关插座&quot;的旅程。</strong> 前端把它包装成了 RPC over MQTT 的模式：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 图示：控制下行链路（RPC over MQTT）</span></span>
<span class="line"><span>[ControlPanel.vue]      [services/mqtt/index.ts]     [broker.mjs]      [simulator.mjs]</span></span>
<span class="line"><span> ① 用户点&quot;开关&quot;按钮</span></span>
<span class="line"><span> ② publishCommand(&#39;switch&#39;)</span></span>
<span class="line"><span>    生成请求 id（uuid）</span></span>
<span class="line"><span> ③ 按钮进入 pending</span></span>
<span class="line"><span>      │</span></span>
<span class="line"><span>      │ ④ QoS 1 发布</span></span>
<span class="line"><span>      ▼</span></span>
<span class="line"><span>    iot/pl01/pl01-001/down/command</span></span>
<span class="line"><span>      ─────────────────────────▶ aedes 转发 ─────▶ ⑤ handleCommand 执行</span></span>
<span class="line"><span>                                                    （setTimeout 300ms 模拟耗时）</span></span>
<span class="line"><span>                                                        │</span></span>
<span class="line"><span>      ⑩ Promise resolve：          ⑨ IotGateway.settle ◀┘ ⑥ 设备 QoS 1 发布</span></span>
<span class="line"><span>        ok / rejected / timeout      按 id 找回 pending ◀── iot/pl01/pl01-001/</span></span>
<span class="line"><span>        按钮状态更新，写指令日志       Promise                down/command_reply</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div><p>三个结果状态值得记住：<code>ok</code>（设备确认执行）、<code>rejected</code>（设备拒绝，如阈值越界）、<code>timeout</code>（<code>commandTimeoutMs = 8000</code>ms 内没等到回执）。<strong>MQTT 发布成功不等于设备执行成功</strong>——中间任何一环都可能断，所以控制类交互必须等业务回执，而不是发完就亮绿灯。</p><h2 id="_1-1-4-部署形态与规模分级" tabindex="-1">1.1.4 部署形态与规模分级 <a class="header-anchor" href="#_1-1-4-部署形态与规模分级" aria-label="Permalink to &quot;1.1.4 部署形态与规模分级&quot;">​</a></h2><p>落地时你大概率不会从零写平台层。两条路线的对比：</p><table tabindex="0"><thead><tr><th>维度</th><th>公有云 IoT 平台（阿里云 IoT / 腾讯云 IoT / 华为云 IoT / AWS IoT Core）</th><th>自建 Broker（EMQX / Mosquitto / aedes）</th></tr></thead><tbody><tr><td>接入规模</td><td>百万级设备，免运维扩容</td><td>单机数百到数万，EMQX 集群可到百万级</td></tr><tr><td>协议与模型</td><td>MQTT/CoAP/HTTP + 平台私有物模型</td><td>标准 MQTT，物模型自己定</td></tr><tr><td>前端对接</td><td>多为平台 REST API + 官方 WebSocket 通道</td><td>自由选择：直连 Broker over WebSocket 或自建 API</td></tr><tr><td>设备安全</td><td>一机一密、动态注册、证书体系</td><td>自己设计认证与权限</td></tr><tr><td>运维成本</td><td>平托管，按消息量/设备数计费</td><td>自己负责集群、持久化、监控告警</td></tr><tr><td>数据主权</td><td>数据在云厂商</td><td>数据完全自持</td></tr><tr><td>适合场景</td><td>快速上线、设备量大、需要整套设备管理</td><td>数据合规敏感、深度定制、成本敏感、教学</td></tr></tbody></table><p>demo 选 aedes 纯粹出于教学考虑：纯内存实现，<code>pnpm install</code> 一次到位，重启即清空，没有任何运维心智负担。真实项目的自建路线一般从 EMQX（企业级、带仪表盘）或 Mosquitto（轻量、久经考验）起步。无论哪条路线，<strong>前端面对的 MQTT 语义是一样的</strong>——本教程的技能可以直接迁移。</p><p>同一套架构，规模差几个数量级，前端的写法就完全不同：</p><table tabindex="0"><thead><tr><th>规模</th><th>设备数</th><th>消息量级</th><th>典型拓扑</th><th>前端设计要点</th></tr></thead><tbody><tr><td>家庭级</td><td>10~100 台</td><td>&lt; 10 条/秒</td><td>单 Broker</td><td>一条 WebSocket 直连即可；通配符全订阅</td></tr><tr><td>园区级</td><td>数百~数万</td><td>数百~数万条/秒</td><td>Broker 集群 + 网关</td><td>快照 API + 增量订阅；前端去重/限流；图表降采样</td></tr><tr><td>城市级</td><td>十万以上</td><td>百万条/秒以上</td><td>多地域集群 + 流处理管道</td><td>前端不直连原始流：走平台 API 拉聚合结果/SSE；列表虚拟化</td></tr></tbody></table><p>demo 是家庭级：8 台设备、每秒约 2~3 条报文，前端可以奢侈地&quot;全量订阅 + 内存滑动窗口&quot;。若把设备数乘上一万，<code>ingestTelemetry</code> 每秒要被调用上万次，不节流的 ECharts 会先死给你看。所以第 1.2 章讨论职责边界、第 4 章讨论性能时，都请带着这张表来思考。</p><h2 id="运行与验证" tabindex="-1">运行与验证 <a class="header-anchor" href="#运行与验证" aria-label="Permalink to &quot;运行与验证&quot;">​</a></h2><p>跑通最小链路，并亲眼看到报文流：</p><div class="language-shell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">shell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 文件: iot-tutorial-project/demo/（在项目根目录执行）</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iot-tutorial-project/demo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # 首次运行先安装依赖</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> server</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">       # 终端 1：同时拉起 Broker（1883/8083）与 8 台模拟设备</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><blockquote><p>运行方式：终端 1 执行 <code>pnpm server</code>；另开终端 2 执行 <code>pnpm dev</code>；浏览器打开 <code>http://localhost:5173</code>（若被占用会顺延 5174，以终端输出为准）。</p></blockquote><p>终端 1 应出现类似输出：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 期望输出（终端 1，来源: demo/server/index.mjs）</span></span>
<span class="line"><span>[broker] TCP 已就绪 mqtt://localhost:1883（设备侧）</span></span>
<span class="line"><span>[broker] WS  已就绪 ws://localhost:8083/mqtt（前端侧）</span></span>
<span class="line"><span>[simulator] 8 台设备正在接入 mqtt://localhost:1883</span></span>
<span class="line"><span>[device] gh01-001 上线（normal）</span></span>
<span class="line"><span>[broker] 接入 +  dev-gh01-001</span></span>
<span class="line"><span>[broker] dev-gh01-001 → iot/gh01/gh01-001/up/status (112B, qos1)</span></span>
<span class="line"><span>[broker] dev-gh01-001 → iot/gh01/gh01-001/up/telemetry (103B, qos0)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>每一行报文日志的格式是：<code>客户端 id → Topic（载荷字节数, QoS 等级）</code>。对照 1.1.3 的上行链路图：<code>dev-gh01-001 → iot/gh01/gh01-001/up/telemetry</code> 就是链路的第 ② 步；浏览器页面上随后出现的曲线，是第 ④~⑦ 步的结果。观察两分钟，你还能看到：</p><ul><li><code>gh01-003</code> 偶发一条 <code>up/event</code>（温度尖峰告警）；</li><li><code>gh01-002</code> 每 15 秒一次性上报 4 个缓存样本（低功耗批量剧本）；</li><li><code>gh01-006</code> 在启动约 40 秒后优雅下线（状态 + 事件双通道）；</li><li><code>gh01-004</code> 从始至终离线——它 retain 的就是 offline 状态。</li></ul><h2 id="最佳实践与常见坑" tabindex="-1">最佳实践与常见坑 <a class="header-anchor" href="#最佳实践与常见坑" aria-label="Permalink to &quot;最佳实践与常见坑&quot;">​</a></h2><ul><li><p><strong>现象</strong>：页面打开后设备列表一直是空的。 <strong>原因</strong>：<code>VITE_MQTT_URL</code> 与 Broker 的 WS 入口对不上（比如只改了端口没改 <a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/.env.development" target="_blank" rel="noreferrer">demo/.env.development</a>），或 Broker 根本没起来。 <strong>解法</strong>：确认终端 1 有 <code>WS 已就绪 ws://localhost:8083/mqtt</code> 这行日志；修改 <code>.env.development</code> 后必须重启 <code>pnpm dev</code>（Vite 不会热更环境变量）。</p></li><li><p><strong>现象</strong>：Broker 重启后，页面上的设备状态停在旧值，新上报也不生效。 <strong>原因</strong>：aedes 是内存实现，重启即清空所有保留消息；而浏览器里旧的组件状态、旧订阅还挂着。 <strong>解法</strong>：刷新页面重新订阅。生产环境要靠&quot;持久化 Broker + 快照查询 API&quot;双保险，不能指望 retain 包打天下。</p></li><li><p><strong>现象</strong>：<code>pnpm server</code> 报端口占用（EADDRINUSE），起不来。 <strong>原因</strong>：上一次的进程没退干净，或 1883/8083 被其他程序占用。 <strong>解法</strong>：<code>lsof -i :8083</code> 找到占用进程 PID 后 <code>kill</code> 掉；或者改端口，并同步修改 <code>.env.development</code>。</p></li><li><p><strong>现象</strong>：遥测停了几秒就把设备标成离线并触发告警，过一会儿设备又&quot;复活&quot;。 <strong>原因</strong>：把&quot;错过一次上报&quot;当成了&quot;设备离线&quot;。无线网络下丢一包是常态。 <strong>解法</strong>：三重在线判定——设备自报 status、Broker 遗嘱、前端看门狗（demo 中 <code>offlineAfterMs = 45000</code>，每 5 秒巡检一次 <code>lastSeenAt</code>，见 <a href="https://github.com/YZhiJie/iot-tutorial-project/blob/main/demo/src/stores/devices.ts" target="_blank" rel="noreferrer">stores/devices.ts</a>）。三重判定都指向离线才告警，且同一次离线只报一次。</p></li></ul><h2 id="实操任务" tabindex="-1">实操任务 <a class="header-anchor" href="#实操任务" aria-label="Permalink to &quot;实操任务&quot;">​</a></h2><ol><li><strong>画一张你自己业务域的链路图</strong>。选一个你熟悉的场景（共享单车、电梯监控、智能仓库都行），仿照 1.1.3 的两张 ASCII 图画出：设备是什么、Broker 在哪、前端用什么协议接入、上行有什么数据、下行有什么指令。提示：先把 Topic 契约定出来，链路图自然就清晰了。</li><li><strong>数报文、估日增量</strong>。把 server 日志重定向到文件：<code>pnpm server 2&gt;&amp;1 | tee /tmp/broker.log</code>，运行整 10 秒后 Ctrl+C，用 <code>grep -c &#39;→ iot/&#39; /tmp/broker.log</code> 统计报文数。提示：结合上报周期估算日增量——普通传感器 4~8 秒一条、低功耗设备 15 秒批量 4 个样本、插座 3~6 秒一条，别忘了还有约 6% 的重复报文。</li></ol><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>[ ] 不看资料能说出四层架构及每层一个代表技术</li><li>[ ] 能画出 demo 的上行链路，并标注 1883 与 8083 两个端口的用途</li><li>[ ] 能解释 retain 与 LWT 各解决什么问题，并指出 demo 源码中的位置</li><li>[ ] 跑通了 demo，并在终端日志中看到了带 Topic 的报文流</li><li>[ ] 亲手发出过一条控制指令，并观察到 ok/rejected/timeout 三态之一</li><li>[ ] 完成了自己业务域的链路图与 10 秒报文计数、日增量估算</li></ul>`,49)])])}const m=n(p,[["render",o]]);export{b as __pageData,m as default};
